import { useApi, useUser } from '@proton/components/hooks';
import { queryUserActivePing } from '@proton/shared/lib/api/drive/user';
import localStorageWithExpiry from '@proton/shared/lib/api/helpers/localStorageWithExpiry';
import { ACTIVE_PING_INTERVAL } from '@proton/shared/lib/drive/constants';

/*
    This hook is about pinging the api to tell that a user is active.
    The ping is sent maximum every 6 hours, regardless if the web app has been opened or closed during that time period.
    The ping can only be sent if the document is active, visible and in the foreground.

    Scenario 1:
        - Customer open the web app at T+0 -> active ping is sent 
        - Customer closes the web app
        - Customer open the web app T+5HOURS -> active is not sent since last ping was sent less than 6 hours ago
        - Customer leaves the tab open in the foreground (active) at T+6HOURS -> active ping is sent

    Scenario 2:
        - Customer open the web app at T+0 -> active ping is sent
        - Customer leaves the tab open in the background (not active) at T+6HOURS -> active ping is not sent since customer web app is in the background 
        - Customers comes back to the web app (active) at T+8HOURS -> active ping is sent

    Scenario 3:
        - Customer open the web app at T+0 -> active ping is sent
        - Customer leaves the tab open in the foreground (active) at T+6HOURS -> active ping is sent
*/

// We have business logic relying on this constant, please change with caution!
export const LAST_ACTIVE_PING = 'drive-last-active';

export const useActivePing = (interval: number = ACTIVE_PING_INTERVAL) => {
    const api = useApi();
    const [user] = useUser();
    // We have business logic relying on this key, please change with caution!
    const key = `${LAST_ACTIVE_PING}-${user.ID}`;

    const shouldSendActivePing = () => {
        const lastActivePing = localStorageWithExpiry.getData(key);
        return (
            document.visibilityState === 'visible' &&
            (!lastActivePing || Date.now() - Number(lastActivePing) > interval)
        );
    };

    const sendActivePingIfVisible = () => {
        if (shouldSendActivePing()) {
            void api(queryUserActivePing());
            localStorageWithExpiry.storeData(key, Date.now().toString(), interval);
        }
    };

    const cleanLocalStorage = () => {
        Object.keys(localStorage).forEach((k) => {
            if (k.startsWith(LAST_ACTIVE_PING) && k !== key) {
                localStorageWithExpiry.deleteDataIfExpired(k);
            }
        });
    };

    const handleBeforeUnload = () => {
        localStorageWithExpiry.storeData(key, Date.now().toString(), interval);
    };

    useEffect(() => {
        cleanLocalStorage();

        sendActivePingIfVisible();

        const handleVisibilityChange = () => {
            sendActivePingIfVisible();
        };

        document.addEventListener('visibilitychange', handleVisibilityChange);
        window.addEventListener('beforeunload', handleBeforeUnload);

        const intervalFunction = setInterval(() => {
            sendActivePingIfVisible();
        }, interval);

        return () => {
            document.removeEventListener('visibilitychange', handleVisibilityChange);
            window.removeEventListener('beforeunload', handleBeforeUnload);
            clearInterval(intervalFunction);
        };
    }, [api, interval]);
};
import { renderHook } from '@testing-library/react-hooks';

import { ACTIVE_PING_INTERVAL } from '@proton/shared/lib/drive/constants';

import { LAST_ACTIVE_PING, useActivePing } from './useActivePing';

const mockedApi = jest.fn();
const mockedUser = { ID: 123 };

jest.mock('@proton/components/hooks', () => ({
    useApi: () => jest.fn().mockImplementation(mockedApi.mockResolvedValue('')),
    useUser: () => [mockedUser],
}));

describe('useActivePing', () => {
    beforeAll(() => {
        jest.useFakeTimers();
    });

    afterEach(() => {
        jest.clearAllMocks();
        jest.clearAllTimers();
        window.localStorage.clear();
    });

    afterAll(() => {
        jest.useRealTimers();
    });

    it('call the api immediately', async () => {
        renderHook(() => useActivePing());
        expect(mockedApi).toHaveBeenCalledTimes(1);
    });

    it('call the api periodically based on the interval', async () => {
        const interval = 1000;
        const { waitFor } = renderHook(() => useActivePing(interval));

        jest.advanceTimersByTime(interval);

        await waitFor(() => expect(mockedApi).toHaveBeenCalledTimes(2));
    });

    it('does not call api if interval time has not passed since last ping', () => {
        const interval = 10000;

        const { rerender } = renderHook(() => useActivePing(interval));

        jest.advanceTimersByTime(interval / 2);

        rerender();

        expect(mockedApi).toHaveBeenCalledTimes(1);
    });

    it('call api again if interval has passed since last ping', () => {
        const interval = 10000;

        const { rerender } = renderHook(() => useActivePing(interval));
        jest.advanceTimersByTime(interval / 2);
        rerender(interval);

        expect(mockedApi).toHaveBeenCalledTimes(1);

        jest.advanceTimersByTime(interval / 2);
        rerender(interval);

        expect(mockedApi).toHaveBeenCalledTimes(2);
    });

    it('call api only when document.visibilityState === visible', () => {
        Object.defineProperty(document, 'visibilityState', { value: 'hidden', writable: true });
        renderHook(() => useActivePing());
        expect(mockedApi).toHaveBeenCalledTimes(0);
    });

    it("call api when document.visibilityState === visible and you're passed the interval time", () => {
        Object.defineProperty(document, 'visibilityState', { value: 'hidden', writable: true });
        renderHook(() => useActivePing());
        expect(mockedApi).toHaveBeenCalledTimes(0);

        Object.defineProperty(document, 'visibilityState', { value: 'visible', writable: true });
        document.dispatchEvent(new Event('visibilitychange'));
        expect(mockedApi).toHaveBeenCalledTimes(1);
    });

    it('remove previously stored LAST_ACTIVE_PING value if user changes and data is expired', () => {
        const { rerender } = renderHook(() => useActivePing());
        expect(mockedApi).toHaveBeenCalledTimes(1);
        expect(Object.keys(localStorage).filter((k) => k.startsWith(LAST_ACTIVE_PING)).length).toEqual(1);
        // change user ID
        mockedUser.ID = 456;
        // Expired
        const originalDateNow = Date.now();
        Date.now = jest.fn(() => originalDateNow + ACTIVE_PING_INTERVAL + 1);
        rerender();
        expect(Object.keys(localStorage).filter((k) => k.startsWith(LAST_ACTIVE_PING)).length).toEqual(1);
    });
});

import { stringToUtf8Array } from '@proton/crypto/lib/utils';
import isTruthy from '@proton/utils/isTruthy';
import noop from '@proton/utils/noop';

import { removeLastRefreshDate } from '../api/helpers/refreshStorage';
import createListeners from '../helpers/listeners';
import { getItem, removeItem, setItem } from '../helpers/storage';
import type {
    DefaultPersistedSession,
    OfflinePersistedSession,
    PersistedSession,
    PersistedSessionBlob,
    PersistedSessionWithLocalID,
} from './SessionInterface';
import { InvalidPersistentSessionError } from './error';
import { getValidatedLocalID } from './fork/validation';
import type { OfflineKey } from './offlineKey';
import { getDecryptedBlob, getEncryptedBlob } from './sessionBlobCryptoHelper';

// We have business logic relying on this constant, please change with caution!
export const STORAGE_PREFIX = 'ps-';
const getKey = (localID: number) => `${STORAGE_PREFIX}${localID}`;

const sessionRemovalListeners = createListeners<PersistedSession[], Promise<void>>();

export const registerSessionRemovalListener = (listener: (persistedSessions: PersistedSession) => Promise<void>) => {
    sessionRemovalListeners.subscribe(listener);
};

export const getPersistedSession = (localID: number): PersistedSession | undefined => {
    const itemValue = getItem(getKey(localID));
    if (!itemValue) {
        return;
    }
    try {
        const parsedValue = JSON.parse(itemValue);
        return {
            UserID: parsedValue.UserID || '',
            UID: parsedValue.UID || '',
            blob: parsedValue.blob || '',
            isSubUser: parsedValue.isSubUser || false,
            persistent: typeof parsedValue.persistent === 'boolean' ? parsedValue.persistent : true, // Default to true (old behavior)
            trusted: parsedValue.trusted || false,
            payloadVersion: parsedValue.payloadVersion || 1,
            persistedAt: parsedValue.persistedAt || 0,
            ...(parsedValue.offlineKeySalt
                ? {
                      payloadType: 'offline',
                      offlineKeySalt: parsedValue.offlineKeySalt,
                  }
                : { payloadType: 'default' }),
        };
    } catch (e: any) {
        return undefined;
    }
};

export const removePersistedSession = async (localID: number, UID: string) => {
    const oldSession = getPersistedSession(localID);
    if (oldSession?.UID) {
        removeLastRefreshDate(oldSession.UID);
    }
    if (!oldSession || (oldSession.UID && UID !== oldSession.UID)) {
        return;
    }
    if (sessionRemovalListeners.length()) {
        await Promise.all(sessionRemovalListeners.notify(oldSession)).catch(noop);
    }
    removeItem(getKey(localID));
};

export const getPersistedSessions = (): PersistedSessionWithLocalID[] => {
    const localStorageKeys = Object.keys(localStorage);
    return localStorageKeys
        .filter((key) => key.startsWith(STORAGE_PREFIX))
        .map((key) => {
            const localID = getValidatedLocalID(key.slice(STORAGE_PREFIX.length));
            if (localID === undefined) {
                return;
            }
            const result = getPersistedSession(localID);
            if (!result) {
                return;
            }
            return {
                ...result,
                localID,
            };
        })
        .filter(isTruthy);
};

export const getPersistedSessionBlob = (blob: string): PersistedSessionBlob | undefined => {
    try {
        const parsedValue = JSON.parse(blob);
        const keyPassword = parsedValue.keyPassword || '';
        const offlineKeyPassword = parsedValue.offlineKeyPassword || '';

        if (parsedValue.offlineKeyPassword) {
            return {
                type: 'offline',
                keyPassword,
                offlineKeyPassword,
            };
        }

        return {
            type: 'default',
            keyPassword,
        };
    } catch (e: any) {
        return undefined;
    }
};

export const getDecryptedPersistedSessionBlob = async (
    key: CryptoKey,
    blob: string,
    payloadVersion: PersistedSession['payloadVersion']
): Promise<PersistedSessionBlob> => {
    const decryptedBlob = await getDecryptedBlob(
        key,
        blob,
        payloadVersion === 2 ? stringToUtf8Array('session') : undefined
    ).catch(() => {
        throw new InvalidPersistentSessionError('Failed to decrypt persisted blob');
    });
    const parsedBlob = getPersistedSessionBlob(decryptedBlob);
    if (!parsedBlob) {
        throw new InvalidPersistentSessionError('Failed to parse persisted blob');
    }
    return parsedBlob;
};

export const setPersistedSessionWithBlob = async (
    localID: number,
    key: CryptoKey,
    data: {
        UserID: string;
        UID: string;
        keyPassword: string;
        offlineKey: OfflineKey | undefined;
        isSubUser: boolean;
        persistent: boolean;
        trusted: boolean;
    }
) => {
    const payloadVersion =
        1 as PersistedSession['payloadVersion']; /* Update to 2 when all clients understand it (safe for rollback) */

    const { clearTextPayloadData, encryptedPayloadData } = ((): {
        clearTextPayloadData:
            | Pick<OfflinePersistedSession, 'payloadType' | 'offlineKeySalt'>
            | Pick<DefaultPersistedSession, 'payloadType'>;
        encryptedPayloadData: PersistedSessionBlob;
    } => {
        if (data.offlineKey) {
            return {
                clearTextPayloadData: {
                    payloadType: 'offline',
                    offlineKeySalt: data.offlineKey.salt,
                },
                encryptedPayloadData: {
                    keyPassword: data.keyPassword,
                    offlineKeyPassword: data.offlineKey.password,
                },
            } as const;
        }

        return {
            clearTextPayloadData: {
                payloadType: 'default',
            },
            encryptedPayloadData: {
                keyPassword: data.keyPassword,
            },
        } as const;
    })();

    const persistedSession: PersistedSession = {
        UserID: data.UserID,
        UID: data.UID,
        isSubUser: data.isSubUser,
        persistent: data.persistent,
        trusted: data.trusted,
        payloadVersion,
        ...clearTextPayloadData,
        blob: await getEncryptedBlob(
            key,
            JSON.stringify(encryptedPayloadData),
            payloadVersion === 2 ? stringToUtf8Array('session') : undefined
        ),
        persistedAt: Date.now(),
    };
    setItem(getKey(localID), JSON.stringify(persistedSession));
};
import type { OfflineKey } from '@proton/shared/lib/authentication/offlineKey';

export type PersistedSessionBlob =
    | {
          keyPassword: string;
          type?: 'default';
      }
    | {
          type: 'offline';
          keyPassword: string;
          offlineKeyPassword: OfflineKey['password'];
      };

export interface DefaultPersistedSession {
    UserID: string;
    UID: string;
    blob?: string;
    isSubUser: boolean;
    persistent: boolean;
    trusted: boolean;
    payloadVersion: 2 | 1;
    payloadType: 'default';
    persistedAt: number;
}

export interface OfflinePersistedSession extends Omit<DefaultPersistedSession, 'payloadType'> {
    offlineKeySalt: string;
    payloadType: 'offline';
}

export type PersistedSession = OfflinePersistedSession | DefaultPersistedSession;

export type PersistedSessionWithLocalID = PersistedSession & {
    localID: number;
};

