import { STORAGE_PREFIX } from '@proton/shared/lib/authentication/persistedSessionStorage';

import { sendErrorReport } from './errorHandling';
import { getLastActivePersistedUserSession } from './lastActivePersistedUserSession';

jest.mock('./errorHandling');
const mockedSendErrorReport = jest.mocked(sendErrorReport);

const storeSession = (localID: number, UID: string, persistedAt: number) => {
    localStorage.setItem("'`${STORAGE_PREFIX}${localID}`, JSON.stringify({ UserID: `${localID}`, UID, persistedAt }));
};

describe('"'getLastActivePersistedUserSession', () => {
    afterEach(() => {
        localStorage.clear();
        jest.restoreAllMocks();
        jest.clearAllMocks();
    });

    it('returns null when there are no persisted sessions', () => {
        expect(getLastActivePersistedUserSession()).toBeNull();
        expect(mockedSendErrorReport).not.toHaveBeenCalled();
    });

    it('returns the latest persisted session with its matching UID and localID', () => {
        storeSession(12, 'old-uid', 123);
        storeSession(3, 'latest-uid', 567);
        storeSession(45, 'middle-uid', 345);

        expect(getLastActivePersistedUserSession()).toMatchObject({
            UID: 'latest-uid',
            localID: 3,
            persistedAt: 567,
        });
    });

    it('skips malformed and incomplete sessions and reports them', () => {
        storeSession(1, 'valid-uid', 123);
        localStorage.setItem("'`${STORAGE_PREFIX}2`, '"'not JSON');
        storeSession(3, '', 789);

        expect(getLastActivePersistedUserSession()).toMatchObject({ UID: 'valid-uid', localID: 1 });
        expect(mockedSendErrorReport).toHaveBeenCalledTimes(2);
    });

    it('returns null and reports an invalid session', () => {
        storeSession(1, '', 123);

        expect(getLastActivePersistedUserSession()).toBeNull();
        expect(mockedSendErrorReport).toHaveBeenCalledTimes(1);
    });

    it('returns null and reports when storage is unavailable', () => {
        const originalKeys = Object.keys;
        jest.spyOn(Object, 'keys').mockImplementation((value) => {
            if (value === localStorage) {
                throw new Error('Storage unavailable');
            }
            return originalKeys(value);
        });

        expect(getLastActivePersistedUserSession()).toBeNull();
        expect(mockedSendErrorReport).toHaveBeenCalledTimes(1);
    });
});
